124	function dechunk(payload: Buffer): Buffer {
125	  const out: Buffer[] = [];
126	  let rest = payload;
127	  for (;;) {
128	    const lineEnd = rest.indexOf('\r\n');
129	    if (lineEnd < 0) break;
130	    const length = parseInt(rest.subarray(0, lineEnd).toString('ascii'), 16);
131	    if (!Number.isFinite(length) || length <= 0) break;
132	    out.push(rest.subarray(lineEnd + 2, lineEnd + 2 + length));
133	    rest = rest.subarray(lineEnd + 2 + length + 2);
134	  }
135	  return Buffer.concat(out);
136	}
