977	// 点击提交、在请求被拦截时（服务端尚未响应）核对按钮状态，并返回浏览器实际发送的载荷。
978	// requestStage=Request 的暂停事件里 request.postData 就是浏览器实际发送的明文请求体。
979	async function submitAndHold(page: CdpPage): Promise<{ requestId: string; payload: any }> {
980	  await page.eval("document.getElementById('product-form').requestSubmit()");
981	  const paused = await page.waitPaused();
982	  assert.equal(paused.request.method, 'POST');
983	  assert.equal(
984	    await page.eval("document.getElementById('submit-btn').disabled"),
985	    true,
986	    '提交进行中提交按钮应暂时不可用',
987	  );
988	  assert.equal(typeof paused.request.postData, 'string', '拦截事件应带实际发送的请求体');
989	  return { requestId: paused.requestId, payload: JSON.parse(paused.request.postData) };
990	}
